import {
    Table,
    TableNameColumn,
    StringColumn,
    BooleanColumn,
    GuidColumn,
    ConditionsColumn,
    ReferenceColumn,
} from '../../db'

export const sysrule_assignment = Table({
    allowWebServiceAccess: true,
    attributes: {
        no_labels: true,
        update_synch: true,
    },
    audit: true,
    extends: 'sysrule',
    extensible: true,
    label: 'Assignment Rule',
    name: 'sysrule_assignment',
    schema: {
        table: TableNameColumn({
            attributes: {
                allow_public: true,
                base_start: true,
                base_table: 'task',
            },
            default: 'incident',
            choices: {
                change_phase: {
                    label: 'Change Phase',
                    sequence: 0,
                },
                change_request: {
                    label: 'Change',
                    sequence: 0,
                },
                change_task: {
                    label: 'Change Task',
                    sequence: 0,
                },
                incident: {
                    label: 'Incident',
                    sequence: 0,
                },
                problem: {
                    label: 'Problem',
                    sequence: 0,
                },
                release_phase: {
                    label: 'Release Phase',
                    sequence: 0,
                },
                release_task: {
                    label: 'Release Task',
                    sequence: 0,
                },
                sc_request: {
                    label: 'Request',
                    sequence: 0,
                },
                sc_req_item: {
                    label: 'Request Item',
                    sequence: 0,
                },
                ticket: {
                    label: 'Ticket',
                    sequence: 0,
                },
            },
            label: 'Table',
        }),
        script: StringColumn({
            default: `/**
* Example:
* The following script requires personalizing the instance to add the Malware category and the Security assignment group.
* if (current.category == "Hardware")
*    current.assignment_group.setDisplayValue("Hardware"); 
* else if (current.category == "Software")
*    current.assignment_group.setDisplayValue("Software");
* else if (current.category == "Malware")
*    current.assignment_group.setDisplayValue("Security");	
*
* Another Example:
* Release Planning Example, which assigns the last person assigned to a release to the current release.
* current.release.product.service.assigned_to;
*/`,
            label: 'Script',
            maxLength: 8000,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                },
            ],
            primary: true,
        }),
        condition: ConditionsColumn({
            dependent: 'table',
            label: 'Conditions',
            maxLength: 1000,
        }),
        group: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Group',
            referenceTable: 'sys_user_group',
        }),
        user: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'User',
            referenceTable: 'sys_user',
        }),
        match_conditions: StringColumn({
            default: 'ALL',
            choices: {
                ALL: {
                    label: 'All',
                    sequence: 0,
                },
                ANY: {
                    label: 'Any',
                    sequence: 0,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Match conditions',
        }),
    },
    textIndex: true,
})
